    }).collect();
    let cmd=Box::leak(Box::new(Command{name:"benchmark",flags:Box::leak(flags.iter().map(|f|f.flag).collect::<Vec<_>>().into_boxed_slice()),args:Box::leak(args.iter().map(|a|a.arg).collect::<Vec<_>>().into_boxed_slice()),subcommands:Box::leak(children.iter().map(|c|c.cmd).collect::<Vec<_>>().into_boxed_slice()),..Command::EMPTY}));
