        let m = cmd.try_get_matches_from_mut(black_box(&clap_argv)).unwrap();
        black_box(shadow_mise_clap::Cli::from_arg_matches(&m)).ok();
    });

    bench("clap: build tree only", || {
        black_box(shadow_mise_clap::Cli::command());
    });
}
