    for _ in 0..7 {
        let start = Instant::now();
        for _ in 0..runs {
            black_box(render());
        }
        best = best.min(start.elapsed().as_secs_f64() * 1e9 / f64::from(runs));
    }
    println!("{label:<32}{best:>10.0} ns");
}

fn main() {
    let spec = shadow_mise::Cli::spec();
    for path in [
